import pandas as pd

df = pd.read_excel('nchs_hus_mammography_use.xlsx', sheet_name='A', header=None)
col_2019 = [c for c in range(df.shape[1]) if str(df.iloc[3, c]).strip() == '2019'][0]

targets = ['50–64 years', '65–74 years']
rates = {}
for r in range(len(df)):
    val = str(df.iloc[r, 0]).strip()
    for t in targets:
        if val.replace('-', '–') == t.replace('-', '–'):
            rates[val] = float(df.iloc[r, col_2019])

result = max(rates, key=rates.get)

import pandas as pd

df = pd.read_excel('nchs_hus_mammography_use.xlsx', sheet_name='A', header=None)
row_idx = None
for r in range(len(df)):
    if 'Total, 40 years and over, age adjusted' in str(df.iloc[r, 0]):
        row_idx = r
        break

year_rates = {}
for c in range(1, df.shape[1]):
    val = str(df.iloc[3, c]).strip()
    if val.isdigit():
        year_rates[val] = float(df.iloc[row_idx, c])

result = str(max(year_rates, key=year_rates.get))

