import pandas as pd
import re

df = pd.read_excel('census_hvs_homeownership_rates_by_region.xlsx', sheet_name='Sheet1', header=None)
current_year = None
mw_val = None
ne_val = None
for idx, row in df.iterrows():
    val = str(row[0]).strip()
    if re.match(r'^\d{4}', val) and not any(r in val for r in ['United', 'Northeast', 'Midwest', 'South', 'West']):
        current_year = val
    elif current_year == '2024':
        if 'Midwest' in val:
            mw_val = float(str(row[3]).replace('*', '').strip())
        elif 'Northeast' in val:
            ne_val = float(str(row[3]).replace('*', '').strip())
result = round(mw_val - ne_val, 1)

import pandas as pd
import re

df = pd.read_excel('census_hvs_homeownership_rates_by_region.xlsx', sheet_name='Sheet1', header=None)
current_year = None
data = {}
target_years = ['2015', '2016', '2017', '2018', '2019']
for idx, row in df.iterrows():
    val = str(row[0]).strip()
    if re.match(r'^\d{4}', val) and not any(r in val for r in ['United', 'Northeast', 'Midwest', 'South', 'West']):
        current_year = val
    elif current_year in target_years and 'United States' in val:
        data[current_year] = float(str(row[4]).replace('*', '').strip())
result = max(data, key=data.get)

import pandas as pd

df = pd.read_excel('ers_food_availability_red_meat_poultry_fish.xlsx', sheet_name='Leading', header=None)

header_row = None
for idx, row in df.iterrows():
    if any('Beef' in str(s) for s in row):
        header_row = idx
        break

beef_col, chicken_col = None, None
for c in range(df.shape[1]):
    val = str(df.iloc[header_row, c])
    if 'Beef' in val:
        beef_col = c
    elif 'Chicken' in val:
        chicken_col = c

first_year = None
for r in range(header_row + 1, len(df)):
    try:
        yr = int(float(df.iloc[r, 0]))
        beef_val = float(df.iloc[r, beef_col])
        chick_val = float(df.iloc[r, chicken_col])
        if chick_val > beef_val:
            first_year = str(yr)
            break
    except (ValueError, TypeError):
        continue

result = first_year

